#include "engine/camera_follow.hpp"
#include "engine/orbit_controller.hpp"
#include "engine/physics.hpp"
#include "engine/collider_component.hpp"
#include "engine/editor.hpp"
#include "engine/editor_play.hpp"
#include "archive_fixture_helpers.hpp"
#include "../src/vehicle_example.hpp"
#include <iostream>
using namespace engine;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
bool near(float a,float b,float tolerance=.002f){return std::abs(a-b)<tolerance;}
template<class F>void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,"Expected camera rejection");}
void targeting(){Scene scene;scene.physics().setGravity({});auto& subject=scene.spawn("Subject");RigidBodySettings b;b.linearDamping=0;subject.addComponent<RigidBodyComponent>("Body",b);subject.addComponent<ColliderComponent>("Collider",CollisionShape::box({.5f,.5f,.5f}));auto& child=subject.addChild<Component>("Offset");child.transform.position={0,1,0};auto& camera=scene.addChild<CameraComponent>("Camera");scene.synchronize();auto& body=*subject.getComponent<RigidBodyComponent>();body.setLinearVelocity({8,0,0});scene.fixedUpdate(.1);scene.physics().setInterpolationAlpha(.5);
 CameraTarget target(subject.id());const auto authoritative=target.resolve(&scene);target.poseSource=CameraPoseSource::Presentation;const auto rendered=target.resolve(&scene);check(near(rendered->m[12],authoritative->m[12]*.5f),"Interpolated actor camera target");CameraTarget sub(child.id());sub.poseSource=target.poseSource;check(near(sub.resolve(&scene)->m[12],rendered->m[12]),"Interpolated descendant camera target");check(near(target.velocity(&scene).x,8),"Physical target velocity");
 CameraFollowSettings settings;settings.enabled=true;settings.target=subject.savedId();settings.collision=false;settings.maxLookAhead=1;camera.setFollow(settings);CameraFollowRig rig(scene,camera.id());const auto pose=subject.transform.matrix().m;rig.update(0,1.5f);check(near(camera.worldPosition().x,rendered->m[12]),"Follow uses sampled pose");check(near(camera.forward().x/camera.forward().z,1.f/8),"Velocity look-ahead clamps to authored maximum");check(subject.transform.matrix().m==pose&&near(body.linearVelocity().x,8),"Camera cannot change simulation");
 const auto eye=camera.worldPosition(),direction=camera.forward();OrbitController orbit(camera,true);orbit.adoptCamera(8);orbit.look(0,0);check(dot(camera.worldPosition()-eye,camera.worldPosition()-eye)<1e-6f&&dot(camera.forward(),direction)>.99999f,"Chase-to-orbit handoff preserves displayed eye and orientation");
 for(float alpha:{0.f,.25f,1.f}){scene.physics().setInterpolationAlpha(alpha);rig.reset();rig.update(.016,1.5);check(near(camera.worldPosition().x,authoritative->m[12]*alpha),"Presentation target independent of visibility/collection");}
 settings.presentationPose=false;camera.setFollow(settings);rig.update(0,1.5);check(near(camera.worldPosition().x,authoritative->m[12]),"Explicit simulation target source");auto bad=settings;bad.lookAheadSeconds=-1;rejects([&]{camera.setFollow(bad);});check(camera.follow().lookAheadSeconds==settings.lookAheadSeconds,"Invalid settings retained");bad=settings;bad.target=camera.savedId();rejects([&]{camera.setFollow(bad);});rejects([&]{rig.update(-1,1);});
 subject.setEnabled(false);const auto frozen=camera.transform.matrix().m;check(!rig.update(.016,1)&&camera.transform.matrix().m==frozen,"Disabled target freezes camera");subject.setEnabled(true);body.teleport(Transform{{30,0,0}});scene.synchronize();rig.reset();rig.update(0,1);check(near(camera.worldPosition().x,30),"Teleport/reset snaps camera history");subject.destroy();scene.flushPendingDestroy();check(!rig.update(.016,1),"Removed target is safe");camera.destroy();scene.flushPendingDestroy();check(!rig.update(.016,1),"Removed camera is safe");}
float smooth(unsigned steps){Scene scene;auto& target=scene.spawn();auto& camera=scene.addChild<CameraComponent>();CameraFollowSettings s;s.enabled=true;s.target=target.savedId();s.collision=false;s.positionHalfLife=.3;camera.setFollow(s);CameraFollowRig rig(scene,camera.id());rig.update(0,1);target.transform.position.x=10;for(unsigned i=0;i<steps;++i)rig.update(1.0/steps,1);return camera.worldPosition().x;}
void collisions(){Scene scene;auto& target=scene.spawn("Target");auto& camera=scene.addChild<CameraComponent>();auto& wall=scene.spawn("Wall");wall.transform.position={0,2,-3};RigidBodySettings body;body.motion=BodyMotion::Static;wall.addComponent<RigidBodyComponent>("Body",body);wall.addComponent<ColliderComponent>("Collider",CollisionShape::box({4,3,.3f}));scene.synchronize();CameraFollowSettings s;s.enabled=true;s.target=target.savedId();camera.setFollow(s);CameraFollowRig rig(scene,camera.id());rig.update(0,1);check(camera.worldPosition().z>-2.7f,"Final collision clips chase boom");s.positionHalfLife=10;camera.setFollow(s);for(int i=0;i<100;++i)rig.update(.01,1);check(camera.worldPosition().z>-2.7f,"Smoothing cannot bypass final collision");}
void persistence(){Scene scene;auto& target=scene.spawn("Subject");auto& camera=scene.addChild<CameraComponent>("Camera");CameraFollowSettings s;s.enabled=true;s.target=target.savedId();s.lookAheadSeconds=.7;camera.setFollow(s);EditorSession editor(scene);editor.select(camera.savedId());check(editor.setProperty("camera.follow.ahead",.9),"Typed follow authoring");check(editor.undo()&&near(camera.follow().lookAheadSeconds,.7),"Follow setting undo");check(editor.redo()&&near(camera.follow().lookAheadSeconds,.9),"Follow setting redo");rejects([&]{editor.setProperty("camera.follow.radius",0.);});check(near(camera.follow().collisionRadius,.3),"Invalid follow edit preserves settings");const RenderView view{&camera};auto bytes=SceneArchive::save(scene,{&view,1});check(bytes[8]==std::byte{34},"Camera archive version34");auto copy=SceneArchive::load(bytes);auto* restored=dynamic_cast<CameraComponent*>(copy.scene->findSavedNode(camera.savedId()));check(restored&&near(restored->follow().lookAheadSeconds,.9)&&restored->follow().target==target.savedId(),"Authored follow persistence");
 EditorPlaySession play;play.start(scene,{&view,1});auto& child=*play.views()[0].camera;auto settings=child.follow();settings.lookAheadSeconds=2;child.setFollow(settings);play.stop();check(bytes==SceneArchive::save(scene,{&view,1}),"Isolated Play does not alter source follow settings");
 Scene old;old.addChild<CameraComponent>();auto legacy=SceneArchive::save(old);stripDefaultCameraFollow(legacy);repairFixture(legacy,25);auto previous=SceneArchive::load(legacy);check(!dynamic_cast<CameraComponent*>(previous.scene->children()[0].get())->follow().enabled,"V25 camera neutral follow defaults");
 auto& group=scene.spawn("Group");auto& subject=group.addChild<Actor>("Nested");auto& nested=group.addChild<CameraComponent>("Nested camera");settings.target=subject.savedId();nested.setFollow(settings);auto duplicated=SceneArchive::duplicateSubtree(group);CameraComponent* cloned=nullptr;Actor* clonedTarget=nullptr;duplicated->visit([&](const Node& n,const Mat4&){if(auto* c=dynamic_cast<const CameraComponent*>(&n))cloned=const_cast<CameraComponent*>(c);if(n.name=="Nested")clonedTarget=const_cast<Actor*>(dynamic_cast<const Actor*>(&n));});check(cloned&&clonedTarget&&cloned->follow().target==clonedTarget->savedId(),"Duplicate remaps internal follow target");}
std::array<Vec3,2> moving(unsigned rate){Scene scene;auto& floor=scene.spawn("Floor");floor.transform.position={0,-.5f,0};RigidBodySettings ground;ground.motion=BodyMotion::Static;floor.addComponent<RigidBodyComponent>("Ground",ground);floor.addComponent<ColliderComponent>("Collider",CollisionShape::box({100,.5f,100}));auto& car=static_cast<Actor&>(scene.adoptChild(makeVehicleExample()));auto& camera=scene.addChild<CameraComponent>();CameraFollowSettings s;s.enabled=true;s.target=car.savedId();camera.setFollow(s);scene.synchronize();car.getComponent<VehicleComponent>()->submit({1,.1f,0,0});CameraFollowRig rig(scene,camera.id());rig.update(0,1.5f);unsigned tick=0;
 for(unsigned frame=0;frame<rate*3;++frame){const double target=double(frame+1)*60/rate;const auto next=unsigned(std::floor(target+1e-8));while(tick<next){scene.fixedUpdate(1.0/60);++tick;}scene.physics().setInterpolationAlpha(float(std::clamp(target-tick,0.0,1.0)));rig.update(1.0/rate,1.5f);}check(tick==180,"Variable render schedule retains fixed ticks");return {car.transform.position,camera.worldPosition()};}
int main(){try{targeting();collisions();persistence();check(near(smooth(30),smooth(144)),"Frame-rate independent camera damping");auto slow=moving(30),fast=moving(144);check(dot(slow[0]-fast[0],slow[0]-fast[0])<1e-6f,"Variable camera schedules preserve vehicle simulation");check(dot(slow[1]-fast[1],slow[1]-fast[1])<.25f*.25f,"30/144 Hz chase composition stays within numerical tolerance");std::cout<<"Camera follow: presentation, velocity, constraints, history, lifecycle and archives passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}

